import{_ as a}from"./chunks/ark_x20_rtk_gps.DQe55Ir8.js";import{_ as r,o as t,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const p=JSON.parse('{"title":"ARK X20 RTK GPS","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/ark_x20_rtk_gps.md","filePath":"uk/dronecan/ark_x20_rtk_gps.md"}'),n={name:"uk/dronecan/ark_x20_rtk_gps.md"};function l(d,e,c,s,h,f){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="ark-x20-rtk-gps" tabindex="-1">ARK X20 RTK GPS <a class="header-anchor" href="#ark-x20-rtk-gps" aria-label="Permalink to &quot;ARK X20 RTK GPS&quot;">​</a></h1><p><a href="https://docs.arkelectron.com/gps/ark-x20-rtk-gps" target="_blank" rel="noreferrer">ARK X20 RTK GPS</a> is an open source <a href="./">DroneCAN</a> <a href="./../gps_compass/rtk_gps">RTK GPS</a>, <a href="https://www.u-blox.com/en/product/zed-x20p-module" target="_blank" rel="noreferrer">u-blox ZED-X20P all-band high precision GNSS module</a>, magnetometer, barometer, IMU, buzzer, and safety switch module.</p><p><img src="'+a+'" alt="ARK X20 RTK GPS"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Замовте цей модуль з:</p><ul><li><a href="https://arkelectron.com/product/ark-x20-rtk-gps/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_RTK_GPS" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>Датчики <ul><li>Ublox ZED-X20P <ul><li>All-band all constellation GNSS receiver</li><li>Best position accuracy and availability in different environments</li><li>RTK, PPP-RTK and PPP algorithms expanding the limits of performance</li><li>Highest quality GNSS raw data</li><li>u-blox end-to-end hardened security</li><li>25Hz update rate</li></ul></li><li>ST IIS2MDC Magnetometer</li><li>Bosch BMP390 Barometer</li><li>Invensense ICM-42688-P 6-Axis IMU</li></ul></li><li>STM32F412VGH6 MCU</li><li>Кнопка безпеки</li><li>Зумер</li><li>Два роз&#39;єми стандарту CAN для Pixhawk (4 контакти JST GH)</li><li>X20 “UART 2” Connector <ul><li>4-контактний JST-GH</li><li>TX, RX, PPS, GND</li></ul></li><li>I2C Expansion Connector <ul><li>4-контактний JST-GH</li><li>5.0V, SCL, SDA, GND</li></ul></li><li>Роз&#39;єм для відлагодження стандарту Pixhawk (6 контактів JST SH)</li><li>LED індикатори <ul><li>Індикатор безпеки</li><li>GPS Fix</li><li>Статус RTK</li><li>RGB Статус системи</li></ul></li><li>USA Built</li><li>Вимоги до живлення <ul><li>5V</li><li>144mA Average</li><li>157mA Max</li></ul></li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>The ARK X20 RTK GPS is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The recommended mounting orientation is with the connectors on the board pointing towards the <strong>back of vehicle</strong>.</p><p>The sensor can be mounted anywhere on the frame, but you will need to specify its position, relative to vehicle centre of gravity, during <a href="#px4-configuration">PX4 configuration</a>.</p><h2 id="налаштування-прошивки" tabindex="-1">Налаштування прошивки <a class="header-anchor" href="#налаштування-прошивки" aria-label="Permalink to &quot;Налаштування прошивки&quot;">​</a></h2><p>ARK X20 RTK GPS runs the <a href="./px4_cannode_fw">PX4 cannode firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><p>ARK X20 RTK GPS boards ship with recent firmware pre-installed, but if you want to build and flash the latest firmware yourself, refer to the <a href="./px4_cannode_fw#building-the-firmware">cannode firmware build instructions</a>.</p><p>Firmware target: <code>ark_can-rtk-gps_default</code> Bootloader target: <code>ark_can-rtk-gps_canbootloader</code></p><h2 id="налаштування-польотного-контролера" tabindex="-1">Налаштування польотного контролера <a class="header-anchor" href="#налаштування-польотного-контролера" aria-label="Permalink to &quot;Налаштування польотного контролера&quot;">​</a></h2><h3 id="увімкнення-dronecan" tabindex="-1">Увімкнення DroneCAN <a class="header-anchor" href="#увімкнення-dronecan" aria-label="Permalink to &quot;Увімкнення DroneCAN&quot;">​</a></h3><p>In order to use the ARK X20 RTK GPS, connect it to the Pixhawk CAN bus and enable the DroneCAN driver by setting parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>).</p><p>Кроки наступні:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> or <code>3</code> and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK X20 RTK GPS CAN to the Pixhawk CAN.</li></ul><p>Після активації модуль буде виявлено при завантаженні. Дані GPS повинні надходити з частотою 10 Гц.</p><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>You need to set necessary <a href="./">DroneCAN</a> parameters and define offsets if the sensor is not centred within the vehicle:</p><ul><li>Enable GPS yaw fusion by setting bit 3 of <a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a> to true.</li><li>Enable GPS blending to ensure the heading is always published by setting <a href="./../advanced_config/parameter_reference#SENS_GPS_MASK">SENS_GPS_MASK</a> to 7 (all three bits checked).</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_GPS">UAVCAN_SUB_GPS</a>, <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_MAG">UAVCAN_SUB_MAG</a>, and <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_BARO">UAVCAN_SUB_BARO</a>.</li><li>The parameters <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX</a>, <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFY">SENS_GPS0_OFFY</a> and <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFZ">SENS_GPS0_OFFZ</a> can be set to account for the offset of the ARK X20 RTK GPS from the vehicles centre of gravity.</li></ul><h3 id="ark-x20-rtk-gps-configuration" tabindex="-1">ARK X20 RTK GPS Configuration <a class="header-anchor" href="#ark-x20-rtk-gps-configuration" aria-label="Permalink to &quot;ARK X20 RTK GPS Configuration&quot;">​</a></h3><p>You may need to <a href="./../dronecan/#qgc-cannode-parameter-configuration">configure the following parameters</a> on the ARK X20 RTK GPS itself:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="CANNODE_NODE_ID"></a><a href="./../advanced_config/parameter_reference#CANNODE_NODE_ID">CANNODE_NODE_ID</a></td><td>CAN node ID (0 for dynamic allocation). If set to 0 (default), dynamic node allocation is used. Set to 1-125 to use a static node ID.</td></tr><tr><td><a id="CANNODE_TERM"></a><a href="./../advanced_config/parameter_reference#CANNODE_TERM">CANNODE_TERM</a></td><td>Вбудована завершення шини CAN. Set to <code>1</code> if this is the last node on the CAN bus.</td></tr><tr><td><a id="GPS_UBX_BAUD1"></a><a href="./../advanced_config/parameter_reference#GPS_UBX_BAUD1">GPS_UBX_BAUD1</a></td><td>UART1 baudrate after the link is auto-detected. Board default is <code>921600</code>.</td></tr><tr><td><a id="GPS_UBX_BAUD2"></a><a href="./../advanced_config/parameter_reference#GPS_UBX_BAUD2">GPS_UBX_BAUD2</a></td><td>UART2 baudrate (default <code>230400</code>).</td></tr></tbody></table><h3 id="setting-up-rover-and-fixed-base" tabindex="-1">Setting Up Rover and Fixed Base <a class="header-anchor" href="#setting-up-rover-and-fixed-base" aria-label="Permalink to &quot;Setting Up Rover and Fixed Base&quot;">​</a></h3><p>Position of the rover is established using RTCM messages from the RTK base module (the base module is connected to QGC, which sends the RTCM information to PX4 via MAVLink).</p><p>Параметри PX4 DroneCAN:</p><ul><li><a href="./../advanced_config/parameter_reference#UAVCAN_PUB_RTCM">UAVCAN_PUB_RTCM</a>: <ul><li>Makes PX4 publish RTCM messages (<a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a>) to the bus (which it gets from the RTK base module via QGC).</li></ul></li></ul><p>Rover module parameters (also <a href="./../dronecan/#qgc-cannode-parameter-configuration">set using QGC</a>):</p><ul><li><a href="./../advanced_config/parameter_reference#CANNODE_SUB_RTCM">CANNODE_SUB_RTCM</a> tells the rover that it should subscribe to <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a> RTCM messages on the bus (from the moving base).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Use <a href="./../advanced_config/parameter_reference#UAVCAN_PUB_MBD">UAVCAN_PUB_MBD</a> and <a href="./../advanced_config/parameter_reference#CANNODE_SUB_MBD">CANNODE_SUB_MBD</a> instead if you want to implement moving base (see below) at the same time.</p></div><p>For more information see <a href="./../dronecan/#rover-and-fixed-base">Rover and Fixed Base</a> in the DroneCAN guide.</p><h2 id="значення-led-індикаторів" tabindex="-1">Значення LED індикаторів <a class="header-anchor" href="#значення-led-індикаторів" aria-label="Permalink to &quot;Значення LED індикаторів&quot;">​</a></h2><ul><li><p>Світлодіоди статусу GPS розташовані праворуч від роз&#39;ємів</p><ul><li>Миготіння зеленого - це фіксація GPS</li><li>Миготіння синього - це отримані корекції та RTK Float</li><li>Сталий синій - це RTK зафіксовано</li></ul></li><li><p>Світлодіоди статусу CAN розташовані зверху ліворуч від роз&#39;ємів</p><ul><li>Повільне блимання зеленого - чекає на підключення CAN</li><li>Швидко блимаюче зелене світло - нормальна робота</li><li>Повільне блимання зеленим і синім - перелік CAN</li><li>Fast blinking blue and red is firmware update in progress</li><li>Миготливий червоний - помилка <ul><li>Якщо ви бачите червоний світлодіод, це означає, що виникла помилка, і вам слід перевірити наступне <ul><li>Переконайтеся, що у польотному контролері встановлено SD-картку</li><li>Make sure the ARK X20 RTK GPS has <code>ark_can-rtk-gps_canbootloader</code> installed prior to flashing <code>ark_can-rtk-gps_default</code></li><li>Видаліть бінарні файли з кореневих та ufw директорій SD-карти та спробуйте зібрати та знову прошити</li></ul></li></ul></li></ul></li></ul><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/gps/ark-x20-rtk-gps" target="_blank" rel="noreferrer">ARK X20 RTK GPS Documentation</a> (ARK Docs)</li></ul>',42)])])}const m=r(n,[["render",l]]);export{p as __pageData,m as default};
